"""architecture：模型设计事实 → 程序校验和推导 → 输出图纸。"""

import time

from pydantic import ValidationError

from app.agent.generation.architecture.design_workflow import draft_design
from app.agent.state import GenerationState
from app.agent.prompts import build_architecture_plan_prompt
from app.agent.runtime import get_reasoning_callback
from app.design.facts import DesignFacts
from app.design.resolve_facts import resolve_facts
from app.llm.errors import model_failure_result


def _validation_reason(exc: ValidationError) -> str:
    """保留字段路径，不把完整候选图纸塞进错误消息。"""
    return "；".join(
        "/"
        + "/".join(map(str, item["loc"]))
        + "："
        + (
            "缺少必填字段"
            if item["type"] == "missing"
            else item["msg"].removeprefix("Value error, ")
        )
        for item in exc.errors(include_input=False, include_url=False)
    )


async def architecture_planner(state: GenerationState) -> dict:
    started = time.perf_counter()
    message = state["user_message"]
    feedback = str(state.get("design_feedback") or "").strip()
    detail_level = state["detail_level"]
    profile_id = state["intent_profile"]
    callback = get_reasoning_callback()
    diagnostics = {
        "schema": "design-facts/1",
        "detail_level": detail_level,
        "profile": profile_id,
        "model_calls": 0,
        "settled": False,
    }
    accepted = {}

    def validate(raw):
        try:
            document = DesignFacts.model_validate(raw)
        except ValidationError as exc:
            raise ValueError(_validation_reason(exc)) from exc
        resolved = resolve_facts(document)
        accepted.update(document=document, resolved=resolved)

    try:
        previous = None
        if feedback and state.get("design_document"):
            try:
                previous = DesignFacts.model_validate(
                    state["design_document"]
                ).model_dump(mode="json", exclude_unset=True)
            except ValidationError:
                diagnostics["last_issue"] = (
                    "上一张图纸不符合新版协议；请先重新生成新版图纸，再提交修改意见"
                )
                return {
                    "status": "failed",
                    "error": diagnostics["last_issue"],
                    "architecture_diag": diagnostics,
                }
        prompt = build_architecture_plan_prompt(
            profile_id=profile_id,
            detail_level=detail_level,
            style_preference=state.get("style_preference"),
        )
        if callback:
            await callback(
                "architecture:progress",
                "正在设计体量、房间、门窗与交通；标高和楼梯参数由程序推导……\n",
            )
        raw = await draft_design(
            base_prompt=prompt,
            user_request=message + ("\n本轮修改意见：" + feedback if feedback else ""),
            current_plan=previous,
            diagnostics=diagnostics,
            validate=validate,
            thinking_mode=state.get("thinking_mode") is not False,
            on_reasoning_delta=callback,
        )
    except Exception as exc:
        diagnostics.update(last_issue=str(exc), settled=False)
        if diagnostics.get("rounds"):
            diagnostics["rounds"][-1]["issue"] = str(exc)
        model_failed = bool(
            diagnostics.get("rounds")
            and diagnostics["rounds"][-1].get("model_call_failed")
        )
        failure = (
            model_failure_result(exc)
            if model_failed
            else {"status": "failed", "error": "设计节点处理失败：" + str(exc)}
        )
        return {**failure, "architecture_diag": diagnostics}
    finally:
        diagnostics["total_ms"] = int((time.perf_counter() - started) * 1000)

    if raw is None:
        return {
            "status": "failed",
            "error": "建筑图纸未通过检查：" + diagnostics["last_issue"],
            "architecture_diag": diagnostics,
        }
    # 未选用的可选字段不用补空数组；单位固定为米。派生参数不写回模型图纸。
    document = accepted["document"].model_dump(mode="json", exclude_unset=True)
    document["units"] = "m"
    return {
        "design_document": document,
        "resolved_design": accepted["resolved"],
        "architecture_diag": diagnostics,
        "design_review_status": "pending",
        "design_feedback": "",
        "error": None,
    }
